// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Interface for SwapRouter contract
interface ISwapRouter {

    function swapExactInputFromStrategy(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        address recipient
